import math
from pathlib import Path

from pyscipopt import Model, quicksum


START = "depot_start"
END = "depot_end"
EARTH_RADIUS_MILES = 3960.0


def great_circle_miles(a, b, radius=EARTH_RADIUS_MILES):
    lat1 = float(a["latitude"])
    lon1 = float(a["longitude"])
    lat2 = float(b["latitude"])
    lon2 = float(b["longitude"])

    deg_to_rad = math.pi / 180.0
    phi1 = (90.0 - lat1) * deg_to_rad
    phi2 = (90.0 - lat2) * deg_to_rad
    theta1 = lon1 * deg_to_rad
    theta2 = lon2 * deg_to_rad

    cos_arc = (
        math.sin(phi1) * math.sin(phi2) * math.cos(theta1 - theta2)
        + math.cos(phi1) * math.cos(phi2)
    )
    cos_arc = max(-1.0, min(1.0, cos_arc))
    return math.acos(cos_arc) * radius


def set_if_available(model, name, value):
    try:
        model.setParam(name, value)
    except Exception:
        pass


def round_int(value, tol=1e-6):
    rounded = int(round(float(value)))
    if abs(float(value) - rounded) > tol:
        raise ValueError(f"expected near-integer value, got {value}")
    return rounded


def extract_route(selected_succ):
    route = [START]
    cur = START
    seen = {START}

    while cur != END:
        if cur not in selected_succ:
            raise RuntimeError(f"route disconnected at {cur!r}")
        nxt = selected_succ[cur]
        if nxt in seen and nxt != END:
            raise RuntimeError(f"cycle detected at {nxt!r}")
        route.append(nxt)
        seen.add(nxt)
        cur = nxt

    return route


def pairwise(items):
    return zip(items, items[1:])


def main():
    data = json.loads(Path("/root/data.json").read_text())

    vehicle_count = int(data["vehicle_count"])
    vehicle_capacity = int(data["vehicle_capacity"])
    penalty_weight = float(data["penalty_weight"])

    depot = {
        "latitude": float(data["depot"]["latitude"]),
        "longitude": float(data["depot"]["longitude"]),
    }

    stations_data = list(data["stations"])
    station_ids = [int(s["id"]) for s in stations_data]
    if len(station_ids) != len(set(station_ids)):
        raise ValueError("duplicate station ids")

    id_to_idx = {sid: idx for idx, sid in enumerate(station_ids)}
    idx_to_id = {idx: sid for sid, idx in id_to_idx.items()}

    station_locations = [
        {
            "latitude": float(s["latitude"]),
            "longitude": float(s["longitude"]),
        }
        for s in stations_data
    ]

    targets = [int(s["net_rebalancing_target"]) for s in stations_data]
    initial_bikes = [int(s["initial_bikes"]) for s in stations_data]
    station_capacity = [int(s["station_capacity"]) for s in stations_data]

    vehicles = range(vehicle_count)
    stations = range(len(stations_data))

    from_nodes = [START, *stations]
    to_nodes = [*stations, END]

    arcs = [
        (i, j)
        for i in from_nodes
        for j in to_nodes
        if i != j and not (i == START and j == END)
    ]

    def node_location(node):
        if node in (START, END):
            return depot
        return station_locations[int(node)]

    distances = {(i, j): great_circle_miles(node_location(i), node_location(j)) for i, j in arcs}

    model = Model("bike_rebalancing")
    model.hideOutput(True)

