            if (i, END) in distances:
                model.addCons(
                    end_load[v] - load_after[v, i] <= M * (1 - x[v, i, END]),
                    name=f"endload_ub_{v}_{i}",
                )
                model.addCons(
                    end_load[v] - load_after[v, i] >= -M * (1 - x[v, i, END]),
                    name=f"endload_lb_{v}_{i}",
                )

