        for node in route_nodes[1:-1]:
            i = int(node)
            svc = round_int(model.getVal(service[v, i]))
            picked = max(svc, 0)
            dropped = max(-svc, 0)
            load_val = round_int(model.getVal(load_after[v, i]))
            stops.append(
                {
                    "station_id": int(idx_to_id[i]),
                    "bikes_picked_up": float(picked),
                    "bikes_dropped_off": float(dropped),
                    "load_after_stop": float(load_val),
                }
            )

        vehicle_reports.append(
            {
                "vehicle_id": int(v + 1),
                "start_load": float(start_load_val),
                "route": route_ids,
                "stops": stops,
                "end_load": float(end_load_val),
            }
        )

    station_reports = []
    total_unmet = 0

    # Collect per-station totals from extracted vehicle reports (to match schema)
    station_totals = {sid: {"pickup": 0, "dropoff": 0} for sid in station_ids}
    for vr in vehicle_reports:
        for stop in vr["stops"]:
            sid = int(stop["station_id"])
            station_totals[sid]["pickup"] += int(round(stop["bikes_picked_up"]))
            station_totals[sid]["dropoff"] += int(round(stop["bikes_dropped_off"]))

    for idx in stations:
        sid = idx_to_id[int(idx)]
        pickup = station_totals[sid]["pickup"]
        dropoff = station_totals[sid]["dropoff"]
        net_change = pickup - dropoff
        unmet_amt = abs(int(targets[idx]) - int(net_change))
        total_unmet += unmet_amt

        station_reports.append(
            {
                "station_id": int(sid),
                "net_rebalancing_target": float(targets[idx]),
                "total_bikes_picked_up": float(pickup),
                "total_bikes_dropped_off": float(dropoff),
                "net_bike_change": float(net_change),
                "unmet_rebalancing_amount": float(unmet_amt),
            }
        )

    # Recompute travel distance from reported routes (authoritative)
    id_to_loc = {sid: station_locations[id_to_idx[sid]] for sid in station_ids}

    def loc_for_report_node(node):
        if node in (START, END):
