    for v in vehicles:
        model.addCons(
            quicksum(x[v, START, j] for j in stations if (START, j) in distances) == 1,
            name=f"start_{v}",
        )
        model.addCons(
            quicksum(x[v, i, END] for i in stations if (i, END) in distances) == 1,
            name=f"end_{v}",
