            "travel_distance_miles": float(travel_distance),
            "unmet_rebalancing_penalty": float(unmet_penalty),
            "total_unmet_rebalancing_amount": float(total_unmet),
        },
        "vehicles": vehicle_reports,
        "stations": station_reports,
    }

    Path("/root/report.json").write_text(json.dumps(report, indent=2, sort_keys=True))

    # Readback check
    loaded = json.loads(Path("/root/report.json").read_text())
    if not isinstance(loaded, dict) or "summary" not in loaded:
